[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a2744;
    --accent: #e8a838;
    --accent2: #3b7dd8;
    --fiction: #3b7dd8;
    --nonfiction: #e8a838;
    --light: #f7f8fc;
    --border: #e2e6ef;
    --text: #1a2744;
    --muted: #6b7a99;
    --positive: #2ecc71;
    --negative: #e74c3c;
    --card-shadow: 0 2px 12px rgba(26,39,68,0.08);
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #f0f2f8;
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }
  /* Header */
  .report-header {
    background: linear-gradient(135deg, var(--primary) 0%, #2d4080 100%);
    color: white;
    padding: 48px 0 40px;
  }
  .header-inner {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 32px;
  }
  .report-badge {
    display: inline-block;
    background: rgba(232,168,56,0.2);
    color: var(--accent);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 20px;
    border: 1px solid rgba(232,168,56,0.4);
    margin-bottom: 16px;
  }
  .report-header h1 {
    font-size: 32px;
    font-weight: 700;
    line-height: 1.2;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
  }
  .report-header .subtitle {
    font-size: 16px;
    color: rgba(255,255,255,0.7);
    max-width: 680px;
  }
  .header-meta {
    display: flex;
    gap: 28px;
    margin-top: 24px;
    padding-top: 24px;
    border-top: 1px solid rgba(255,255,255,0.12);
    flex-wrap: wrap;
  }
  .meta-item { font-size: 13px; color: rgba(255,255,255,0.6); }
  .meta-item strong { color: white; }
  /* Layout */
  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 32px 60px;
  }
  /* Section */
  .section {
    margin-top: 48px;
  }
  .section-header {
    display: flex;
    align-items: baseline;
