    padding: 24px;
    box-shadow: var(--card-shadow);
    border: 1px solid var(--border);
  }
  .card-title {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 16px;
  }
  /* KPI Grid */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(175px, 1fr));
    gap: 16px;
    margin-bottom: 0;
  }
  .kpi-card {
    background: white;
    border-radius: 12px;
    padding: 20px 24px;
    box-shadow: var(--card-shadow);
    border: 1px solid var(--border);
  }
  .kpi-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 8px;
  }
  .kpi-value {
    font-size: 32px;
    font-weight: 800;
    color: var(--primary);
    letter-spacing: -1px;
    line-height: 1;
  }
  .kpi-sub {
    font-size: 12px;
    color: var(--muted);
    margin-top: 4px;
  }
  .kpi-accent { color: var(--accent); }
  .kpi-accent2 { color: var(--accent2); }
  /* Two-column layout */
  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }
  .three-col {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
  }
  @media (max-width: 768px) {
    .two-col, .three-col { grid-template-columns: 1fr; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .header-inner h1 { font-size: 24px; }
