  .winner-fiction { background: rgba(59,125,216,0.12); color: var(--fiction); }
  .winner-nonfiction { background: rgba(232,168,56,0.15); color: #b07d10; }
  /* Chart containers */
  .chart-wrap {
    position: relative;
    width: 100%;
    height: 320px;
  }
  .chart-wrap-tall {
    position: relative;
    width: 100%;
    height: 380px;
  }
  .chart-wrap-sm {
