  }
  .corr-genre { font-size: 13px; min-width: 90px; }
  .corr-bar-wrap {
    flex: 1;
    height: 8px;
    background: #eef0f7;
    border-radius: 4px;
    overflow: hidden;
  }
  .corr-bar-fill {
