<body>

<!-- ═══════════════════════════  HEADER  ═══════════════════════════ -->
<div class="report-header">
  <div class="header-inner">
    <div class="report-badge">Management Report · Trend Analysis</div>
    <h1>Amazon Bestselling Books<br>Price vs. User Rating (2009–2019)</h1>
    <p class="subtitle">A decade-long analysis of how pricing strategies relate to customer satisfaction across Fiction and Non-Fiction genres on Amazon's annual bestseller lists.</p>
    <div class="header-meta">
      <div class="meta-item"><strong>Dataset:</strong> 550 records · 11 years · 2 genres</div>
      <div class="meta-item"><strong>Source:</strong> Amazon Top 50 Bestsellers, 2009–2019</div>
      <div class="meta-item"><strong>Analysis Date:</strong> April 2026</div>
      <div class="meta-item"><strong>Audience:</strong> Senior Management</div>
    </div>
  </div>
</div>

<div class="container">

<!-- ═══════════════════════════  SECTION 1: MARKET OVERVIEW  ═══════════════════════════ -->
<div class="section">
  <div class="section-header">
    <span class="section-number">01</span>
    <h2 class="section-title">Bestseller Market Overview (2009–2019)</h2>
  </div>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">Total Records</div>
      <div class="kpi-value">550</div>
      <div class="kpi-sub">50 books × 11 years</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Unique Titles</div>
      <div class="kpi-value">351</div>
      <div class="kpi-sub">199 multi-year repeats</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Avg User Rating</div>
      <div class="kpi-value kpi-accent">4.62</div>
      <div class="kpi-sub">out of 5.0</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Avg Book Price</div>
      <div class="kpi-value">$13.10</div>
      <div class="kpi-sub">range: $0 – $105</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Avg Review Count</div>
      <div class="kpi-value kpi-accent2">11,953</div>
      <div class="kpi-sub">per bestselling entry</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Total Reviews</div>
      <div class="kpi-value">6.57M</div>
      <div class="kpi-sub">cumulative across all records</div>
    </div>
  </div>

  <div class="two-col mt-4">
    <div class="card">
      <div class="card-title">Genre Distribution (by record count)</div>
