// Year table
const yearTbody = document.getElementById('yearTableBody');
yoyData.forEach((row, i) => {
  const prevPrice = i > 0 ? yoyData[i-1].avg_price : null;
  const prevRating = i > 0 ? yoyData[i-1].avg_rating : null;
  const priceDir = prevPrice === null ? '' : row.avg_price < prevPrice
    ? `<span style="color:#2ecc71;font-weight:700;">▼ ${(prevPrice - row.avg_price).toFixed(2)}</span>`
    : `<span style="color:#e74c3c;font-weight:700;">▲ ${(row.avg_price - prevPrice).toFixed(2)}</span>`;
  const ratingDir = prevRating === null ? '' : row.avg_rating > prevRating
    ? `<span style="color:#2ecc71;font-weight:700;">▲ ${(row.avg_rating - prevRating).toFixed(2)}</span>`
    : row.avg_rating < prevRating
      ? `<span style="color:#e74c3c;font-weight:700;">▼ ${(prevRating - row.avg_rating).toFixed(2)}</span>`
      : `<span style="color:#999;">—</span>`;
  yearTbody.innerHTML += `<tr>
    <td><strong>${row.year}</strong></td>
    <td>$${row.avg_price.toFixed(2)}</td>
    <td>${row.avg_rating.toFixed(2)}</td>
    <td>${row.avg_reviews.toLocaleString()}</td>
    <td style="color:#3b7dd8;font-weight:600;">${row.fiction_count}</td>
    <td style="color:#b07d10;font-weight:600;">${row.nonfiction_count}</td>
    <td>${priceDir}</td>
    <td>${ratingDir}</td>
  </tr>`;
});

